package com.example.com.englishai.backend.infrastructure.persistence.mapper; import org.springframework.stereotype.Component; import com.example.com.englishai.backend.domain.authentication.PasswordResetCode; import com.example.com.englishai.backend.infrastructure.persistence.entity.PasswordResetCodeEntity;
@Component public class PasswordResetCodeMapper { public PasswordResetCode toDomain(PasswordResetCodeEntity e){return new PasswordResetCode(e.getId(),e.getUserId(),e.getCodeHash(),e.getCreatedAt(),e.getExpiresAt(),e.getUsedAt(),e.getInvalidatedAt(),e.getAttempts(),e.getMaxAttempts());} public PasswordResetCodeEntity toEntity(PasswordResetCode c){return new PasswordResetCodeEntity(c.getId(),c.getUserId(),c.getCodeHash(),c.getCreatedAt(),c.getExpiresAt(),c.getUsedAt(),c.getInvalidatedAt(),c.getAttempts(),c.getMaxAttempts());} }
